{"code": "def solve():
    row_targets = [7, 14, 28, 7, 5, 5, 1, 15, 1]
    col_targets = [16, 11, 6, 11, 18, 10, 3, 5, 3]
    n = 9
    grid = [[0]*n for _ in range(n)]

    def backtrack(r, c):
        if r == n:
            return True

        nr, nc = (r, c + 1) if c < n - 1 else (r + 1, 0)

        # Try 1
        grid[r][c] = 1
        if is_feasible(r, c):
            if backtrack(nr, nc):
                return True

        # Try 0
        grid[r][c] = 0
        if is_feasible(r, c):
            if backtrack(nr, nc):
                return True

        return False

    def is_feasible(r, c):
        # Row sum check
        row_sum = sum((j+1) for j in range(c + 1) if grid[r][j] == 1)
        if c == n - 1:
            if row_sum != row_targets[r]: return False
        else:
            if row_sum > row_targets[r]: return False

        # Column sum check
        col_sum = sum((i+1) for i in range(r + 1) if grid[i][c] == 1)
        if r == n - 1:
            if col_sum != col_targets[c]: return False
        else:
            if col_sum > col_targets[c]: return False

        return True

    if backtrack(0, 0):
        return grid
    return None

sol = solve()
if sol:
    for row in sol:
        print(' '.join(map(str, row)))"}

